-- 개인 개발 DB 전용 가상 사용자·리뷰 데이터. 실제 이용자의 활동이 아니다.
-- 예약 ID: 900001~900054. 운영·공용 DB에 실행하지 않는다.
BEGIN;
-- 개발용 데이터만 정책에 맞게 다시 구성한다.
UPDATE feedback_comments SET is_adopted = false, adopted_at = NULL
WHERE comment_id BETWEEN 900001 AND 900054;
ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, nickname = EXCLUDED.nickname;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title;
ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content;
ON CONFLICT (comment_id) DO UPDATE SET feedback_id = EXCLUDED.feedback_id, user_id = EXCLUDED.user_id, section = EXCLUDED.section, content = EXCLUDED.content, is_adopted = EXCLUDED.is_adopted, adopted_at = EXCLUDED.adopted_at, created_at = EXCLUDED.created_at;
UPDATE feedback_comments SET is_adopted = true, adopted_at = created_at
WHERE comment_id IN (
    SELECT DISTINCT ON (feedback_id) comment_id FROM feedback_comments
    WHERE comment_id BETWEEN 900001 AND 900054
    ORDER BY feedback_id, comment_id
);
ON CONFLICT (id) DO UPDATE SET comment_id = EXCLUDED.comment_id, period = EXCLUDED.period, period_start = EXCLUDED.period_start, rank_no = EXCLUDED.rank_no, created_at = EXCLUDED.created_at;
ON CONFLICT (comment_id, user_id) DO NOTHING;
COMMIT;
