INSERT INTO feedback_comments (comment_id, feedback_id, user_id, section, content, is_adopted, adopted_at, created_at) VALUES
(900001, 900002, '00000000-0000-4000-8000-000000900004', '프로젝트', '장바구니 화면에서 선택한 상품 수가 늘어날 때 느려졌다는 사례가 좋았어요. 처음부터 메모이제이션을 적용하기보다 어떤 컴포넌트가 반복해서 렌더링됐는지 확인한 과정을 추가해 주세요. 개선 전후를 같은 조건에서 측정했다는 설명도 있으면 좋겠습니다.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '0 weeks')::date + INTERVAL '2 days'),
(900002, 900003, '00000000-0000-4000-8000-000000900009', '기술 역량', '예약 API에서 마지막 좌석을 두 사람이 동시에 선택하는 상황을 어떻게 처리했나요? 단순히 트랜잭션을 적용했다고 적기보다 낙관적 락과 비관적 락 중 무엇을 선택했고 충돌한 사용자에게 어떤 응답을 줬는지 보여 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '0 weeks')::date + INTERVAL '2 days'),
(900003, 900004, '00000000-0000-4000-8000-000000900014', '경력 소개', '첫 문장의 “어떤 일이든 열심히 하는 개발자”는 본인의 특징이 잘 안 드러나요. 뒤에 적힌 고객 문의를 분석해 검색 기능을 고친 경험을 소개 첫머리로 옮겨 보면 어떨까요? 문제를 발견하는 방식이 더 잘 전달될 것 같아요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '0 weeks')::date + INTERVAL '2 days'),
(900004, 900005, '00000000-0000-4000-8000-000000900001', '사용자 경험', '이미지 업로드 실패 후 입력한 글까지 사라지는 문제를 해결한 부분이 인상적이에요. 임시 저장 위치와 재시도할 때 중복 업로드를 막은 방법까지 적으면 사용자의 불편을 끝까지 다뤘다는 점이 보일 거예요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '1 weeks')::date + INTERVAL '2 days'),
(900005, 900007, '00000000-0000-4000-8000-000000900006', '협업', '팀장이었다는 직책보다 의견이 갈렸던 순간의 행동을 적어 주세요. 실제로 기술 선택 기준을 정리하고 작은 실험으로 합의했다면, 비교한 항목과 결정 결과를 짧게 넣는 편이 더 설득력 있어요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '1 weeks')::date + INTERVAL '2 days'),
(900006, 900007, '00000000-0000-4000-8000-000000900011', '문제 해결', '운영 중 메모리 사용량이 증가한 사례에서 원인을 바로 결론 내리지 않은 점이 좋았어요. 힙 덤프에서 어떤 객체가 남아 있었고 수정 후 재현 조건에서 다시 확인했는지까지 이어 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '1 weeks')::date + INTERVAL '2 days'),
(900007, 900008, '00000000-0000-4000-8000-000000900016', '테스트', '테스트 커버리지 수치는 있는데 무엇을 보호하는 테스트인지 잘 안 보여요. 쿠폰 사용 기한 직전과 직후, 이미 사용한 쿠폰을 다시 제출하는 경우처럼 실제로 놓치기 쉬운 조건을 두 개 정도 골라 소개해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '2 weeks')::date + INTERVAL '2 days'),
(900008, 900009, '00000000-0000-4000-8000-000000900003', '데이터베이스', '게시글 검색에 인덱스를 추가한 경험은 검색어 패턴에 따라 결과가 달랐을 것 같아요. 앞부분 일치와 중간 문자열 검색을 구분해서 어떤 쿼리를 개선했는지 적어 주면 성능 수치를 이해하기 쉬워요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '2 weeks')::date + INTERVAL '2 days'),
(900009, 900010, '00000000-0000-4000-8000-000000900008', '배포', '배포 실패 후 이전 버전으로 복구한 경험이 있다면 별도 항목으로 넣어도 좋겠어요. 이미지 태그를 어떻게 관리했고 DB 변경과 애플리케이션 버전이 맞지 않을 때는 어떻게 대응했는지가 궁금해요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '2 weeks')::date + INTERVAL '2 days'),
(900010, 900011, '00000000-0000-4000-8000-000000900013', '접근성', '모달을 닫은 뒤 키보드 포커스가 원래 버튼으로 돌아가도록 수정한 건 작지만 좋은 사례예요. 화면 캡처만으로 보이지 않는 개선이니 직접 확인한 키보드 흐름을 한 문장으로 설명해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '3 weeks')::date + INTERVAL '2 days'),
(900011, 900012, '00000000-0000-4000-8000-000000900018', '문서화', '환경 설정 문서에 모든 옵션을 나열하기보다는 처음 실행하는 사람이 필요한 순서대로 안내해 보세요. 설치, 환경 변수, DB 준비, 실행 확인을 나누고 자주 발생했던 오류를 끝에 붙이면 읽기 쉬워질 것 같아요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '3 weeks')::date + INTERVAL '2 days'),
(900012, 900001, '00000000-0000-4000-8000-000000900005', '프로젝트 구조', '공통 버튼에 페이지별 조건이 계속 추가되는 부분이 보여요. 버튼은 크기와 상태 표현만 맡기고 저장·지원·결제 동작은 사용하는 쪽에서 넘겼다고 설명하면 컴포넌트를 나눈 기준이 명확해져요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '3 weeks')::date + INTERVAL '2 days'),
(900013, 900002, '00000000-0000-4000-8000-000000900010', 'API 설계', '프로필 진입 때 요청이 여러 번 발생했던 상황을 그림으로 보여 주면 좋겠어요. 항상 함께 필요한 위젯 설정을 대표 응답에 포함한 이유와, 따로 조회해야 하는 데이터는 무엇인지 구분해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '4 weeks')::date + INTERVAL '2 days'),
(900014, 900003, '00000000-0000-4000-8000-000000900015', '보안', '파일 다운로드 API에서 로그인 확인만으로 접근을 허용하면 다른 사람의 이력서를 받을 수 있어요. 요청한 파일의 소유자나 공개 상태를 서버에서 검사했다면 해당 검증을 보안 경험으로 구체화해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '4 weeks')::date + INTERVAL '2 days'),
(900015, 900004, '00000000-0000-4000-8000-000000900002', '회고', '회고에 “소통이 중요했다”는 문장이 반복돼요. 요구사항 해석이 달라 재작업한 기능 하나를 고르고, 이후 어떤 문서나 확인 절차를 추가했는지 적으면 경험에서 배운 점이 선명해져요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '4 weeks')::date + INTERVAL '2 days'),
(900016, 900005, '00000000-0000-4000-8000-000000900007', '포트폴리오', '포트폴리오 첫 화면에 기능 소개가 너무 많아서 본인이 맡은 영역을 찾기 어려웠어요. 프로젝트 요약 바로 아래에 담당 범위 세 줄과 대표 문제 해결 한 건을 배치해 보세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '5 weeks')::date + INTERVAL '2 days'),
(900017, 900006, '00000000-0000-4000-8000-000000900012', '캐시', '인기 게시글 캐시에서 수정된 제목이 늦게 반영되는 문제도 다뤘나요? 조회 속도 수치와 함께 허용한 지연 시간, 갱신 조건, 캐시 장애 시 동작을 적으면 운영 판단을 보여 줄 수 있어요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '5 weeks')::date + INTERVAL '2 days'),
(900018, 900007, '00000000-0000-4000-8000-000000900017', '비동기 처리', '검색어를 빠르게 입력하면 이전 결과가 덮어쓰던 문제를 설명한 부분이 좋아요. 디바운스와 요청 취소가 각각 해결하는 문제가 다르다는 점을 본인의 구현 흐름에 맞춰 짧게 덧붙여 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '5 weeks')::date + INTERVAL '2 days'),
(900019, 900008, '00000000-0000-4000-8000-000000900004', '프로젝트', '결제 금액을 double로 계산한 코드는 수정하는 게 좋겠어요. 할인과 반올림이 어느 단계에서 적용되는지 정하고, 원 단위 정수나 BigDecimal을 사용한 이유를 설명하면 데이터 처리의 정확성을 보여 줄 수 있어요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '6 weeks')::date + INTERVAL '2 days'),
(900020, 900010, '00000000-0000-4000-8000-000000900009', '기술 역량', '팀 프로젝트에서 만든 기능 수보다 이미 있는 코드를 이해하고 수정한 경험이 더 눈에 띄었어요. 낯선 모듈의 호출 경로를 어떻게 추적했고 기존 동작을 깨뜨리지 않도록 무엇을 확인했는지 적어 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '6 weeks')::date + INTERVAL '2 days'),
(900021, 900010, '00000000-0000-4000-8000-000000900014', '경력 소개', '모바일 메뉴를 만들었다는 설명에 작은 화면에서 포기한 정보와 유지한 동작을 넣어 보세요. 데스크톱을 단순히 줄인 것이 아니라 사용 우선순위에 따라 배치했다는 점이 드러나면 좋아요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '6 weeks')::date + INTERVAL '2 days'),
(900022, 900011, '00000000-0000-4000-8000-000000900001', '사용자 경험', '회원 탈퇴 시 데이터를 모두 삭제했다고 적혀 있는데 주문이나 결제 이력은 어떻게 보존했나요? 직접 설계한 범위 안에서 개인정보와 업무 기록의 처리 기준을 나눠 설명해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '7 weeks')::date + INTERVAL '2 days'),
(900023, 900012, '00000000-0000-4000-8000-000000900006', '협업', '외부 API 장애를 try-catch로 처리했다는 문장만으로는 사용자가 어떤 화면을 봤는지 알기 어려워요. 시간 제한, 재시도 조건, 실패 안내와 기존 데이터 유지 여부까지 적어 주면 좋겠습니다.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '7 weeks')::date + INTERVAL '2 days'),
(900024, 900001, '00000000-0000-4000-8000-000000900011', '문제 해결', '기술 목록에서 사용 경험과 학습 중인 도구가 섞여 있어요. 실제 프로젝트에서 문제를 해결한 기술을 먼저 두고, 강의를 따라 써 본 기술은 별도로 정리하면 질문을 받았을 때도 설명하기 편할 거예요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '7 weeks')::date + INTERVAL '2 days'),
(900025, 900002, '00000000-0000-4000-8000-000000900016', '테스트', '페이지 이동 후에도 목록 필터가 유지되는 개선이 사용자 입장에서 좋았을 것 같아요. URL에 저장한 값과 화면 안에서만 관리한 상태를 구분해서 왜 그렇게 나눴는지 보여 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '8 weeks')::date + INTERVAL '2 days'),
(900026, 900004, '00000000-0000-4000-8000-000000900003', '데이터베이스', '로그에 토큰이나 이메일 전체가 남지 않도록 바꾼 경험은 충분히 가치 있어요. 어떤 정보를 가렸는지뿐 아니라 장애 추적에 필요한 요청 식별자는 어떻게 유지했는지 함께 적어 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '8 weeks')::date + INTERVAL '2 days'),
(900027, 900004, '00000000-0000-4000-8000-000000900008', '배포', '새로운 라이브러리를 도입한 이유가 “많이 사용해서”로 끝나 아쉬워요. 기존 구현의 불편, 비교한 대안, 의존성을 늘리고도 얻은 이점을 같은 기준으로 정리해 보세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '8 weeks')::date + INTERVAL '2 days'),
(900028, 900005, '00000000-0000-4000-8000-000000900013', '접근성', 'DB 연결 풀이 고갈됐던 사건은 동시 요청 수와 연결 점유 시간을 같이 보여 주면 이해하기 쉬워요. 풀 크기를 늘리는 것 외에 오래 열린 트랜잭션이나 외부 호출을 분리했는지 궁금해요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '9 weeks')::date + INTERVAL '2 days'),
(900029, 900006, '00000000-0000-4000-8000-000000900018', '문서화', 'Git 협업 경험을 브랜치 이름만으로 설명하지 않아도 돼요. 같은 파일을 수정하다 충돌했을 때 변경 의도를 확인하고 통합한 사례를 적으면 실제 협업 방식이 드러나요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '9 weeks')::date + INTERVAL '2 days'),
(900030, 900007, '00000000-0000-4000-8000-000000900005', '프로젝트 구조', '글로벌 상태에 모든 입력값을 넣었다가 폼 내부 상태로 옮긴 사례가 흥미로워요. 여러 화면이 공유해야 하는 값과 작성 중에만 필요한 값을 구분한 기준을 넣어 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '9 weeks')::date + INTERVAL '2 days'),
(900031, 900008, '00000000-0000-4000-8000-000000900010', 'API 설계', '에러 메시지를 “실패했습니다”에서 구체적인 안내로 바꾼 경험을 살려 보세요. 사용자가 입력을 고쳐야 하는 경우와 잠시 후 다시 시도해야 하는 경우를 어떻게 나눴는지 보여 주면 좋아요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '10 weeks')::date + INTERVAL '2 days'),
(900032, 900009, '00000000-0000-4000-8000-000000900015', '보안', '조회 쿼리의 실행 시간이 줄었다는 그래프에 데이터 규모와 실행 환경이 빠져 있어요. 캐시가 비어 있는 상태인지, 몇 번 측정한 값인지 정도는 함께 적어야 결과를 비교할 수 있어요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '10 weeks')::date + INTERVAL '2 days'),
(900033, 900010, '00000000-0000-4000-8000-000000900002', '회고', '처음 설계한 ERD와 최종 구조가 달라진 이유를 설명해 주세요. 화면 요구가 바뀌어 관계를 분리한 건지, 중복 저장 때문에 갱신 문제가 생긴 건지 구체적인 계기가 있으면 설계 경험이 살아나요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '10 weeks')::date + INTERVAL '2 days'),
(900034, 900011, '00000000-0000-4000-8000-000000900007', '포트폴리오', '알림을 비동기로 보낸 이유를 응답 속도만으로 설명하기보다 실패했을 때의 처리도 적어 보세요. 본 작업은 성공했는데 알림만 실패한 경우를 구분했다면 중요한 설계 포인트예요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '11 weeks')::date + INTERVAL '2 days'),
(900035, 900001, '00000000-0000-4000-8000-000000900012', '캐시', '오픈소스 기여는 PR이 병합됐다는 결과 외에 이슈를 재현한 과정도 좋아 보여요. 최소 재현 예제를 만들고 유지보수자의 피드백에 따라 어떤 부분을 수정했는지 추가해 주세요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '11 weeks')::date + INTERVAL '2 days'),
(900036, 900001, '00000000-0000-4000-8000-000000900017', '비동기 처리', '목록 API에서 페이지 크기 상한을 둔 이유를 설명하면 좋겠어요. 큰 요청으로 응답과 DB 부하가 늘어나는 상황을 고려했다면 입력 검증도 단순 형식 검사 이상의 경험으로 보여 줄 수 있어요.', false, NULL, (date_trunc('week', CURRENT_DATE) - INTERVAL '11 weeks')::date + INTERVAL '2 days'),
(900037, 900002, '00000000-0000-4000-8000-000000900004', '프로젝트', '이전 직무에서 고객과 요구사항을 조율한 경험을 빼지 않아도 돼요. 개발 직무와 직접 연결되는 문제 정의, 우선순위 조정, 결과 확인 위주로 줄이면 강점이 될 수 있어요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '0 months')::date + INTERVAL '2 days'),
(900038, 900003, '00000000-0000-4000-8000-000000900009', '기술 역량', '실시간 채팅에서 연결이 끊겼을 때 메시지를 어떻게 복구했는지가 궁금해요. 다시 접속한 사용자에게 누락된 메시지를 보내는 기준과 중복 표시를 막은 방법을 적어 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '0 months')::date + INTERVAL '2 days'),
(900039, 900004, '00000000-0000-4000-8000-000000900014', '경력 소개', '로그인 직후 화면이 잠깐 로그아웃 상태로 보였던 문제를 다뤘다면 좋은 소재예요. 서버와 브라우저의 첫 상태를 어떻게 맞췄는지, 로딩 상태는 어디에 뒀는지 설명해 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '0 months')::date + INTERVAL '2 days'),
(900040, 900005, '00000000-0000-4000-8000-000000900001', '사용자 경험', '데이터를 삭제하는 배치 작업에는 실패 후 재실행해도 괜찮은지 확인한 내용이 필요해요. 처리 단위를 나누거나 완료 지점을 기록했다면 큰 데이터 작업을 안전하게 다룬 경험이 될 거예요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '1 months')::date + INTERVAL '2 days'),
(900041, 900007, '00000000-0000-4000-8000-000000900006', '협업', '팀원의 코드 리뷰를 도왔다는 설명을 구체화해 보세요. 취향 차이인 부분과 실제 오류 가능성이 있는 부분을 구분하고, 상대가 확인할 수 있는 근거를 제시한 사례가 좋겠어요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '1 months')::date + INTERVAL '2 days'),
(900042, 900007, '00000000-0000-4000-8000-000000900011', '문제 해결', '기능 구현 속도를 높였다는 문장에 반복 작업을 줄인 대상을 넣어 주세요. API 응답 타입 생성이나 테스트 데이터 준비처럼 무엇을 자동화했는지 알면 개선의 범위를 이해하기 쉬워요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '1 months')::date + INTERVAL '2 days'),
(900043, 900008, '00000000-0000-4000-8000-000000900016', '테스트', '다국어 화면에서 날짜와 금액을 직접 문자열로 붙이지 않은 점이 좋아요. 표시 형식과 서버에 저장하는 값을 분리하고 사용자의 시간대를 처리한 사례를 한 줄 보태 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::date + INTERVAL '2 days'),
(900044, 900009, '00000000-0000-4000-8000-000000900003', '데이터베이스', '지원 동기에 회사의 기술 이름을 나열하기보다 제품에서 관심을 가진 문제를 적어 보세요. 본인의 프로젝트에서 비슷한 문제를 다뤘던 경험으로 연결하면 지원 이유가 자연스러워져요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::date + INTERVAL '2 days'),
(900045, 900010, '00000000-0000-4000-8000-000000900008', '배포', '대용량 파일을 한 번에 메모리로 읽던 코드를 스트리밍으로 바꾼 경험은 수치로 보여 주기 좋아요. 파일 크기별 최대 메모리와 실패한 행을 어떻게 안내했는지까지 정리해 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::date + INTERVAL '2 days'),
(900046, 900011, '00000000-0000-4000-8000-000000900013', '접근성', '메시지 큐를 사용했다고 해서 중복 처리가 자동으로 막히지는 않아요. 같은 이벤트가 다시 도착했을 때 주문 상태가 두 번 바뀌지 않도록 어떤 키나 조건을 사용했는지 설명해 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '3 months')::date + INTERVAL '2 days'),
(900047, 900012, '00000000-0000-4000-8000-000000900018', '문서화', '브라우저 뒤로 가기 후 작성 내용이 사라지는 문제를 해결한 사례가 눈에 띄어요. 저장 주기와 복원 조건, 제출 완료 후 임시 내용을 지우는 시점을 함께 적으면 완결된 경험이 돼요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '3 months')::date + INTERVAL '2 days'),
(900048, 900001, '00000000-0000-4000-8000-000000900005', '프로젝트 구조', '추상화를 도입한 이유가 클래스 수를 줄이기 위해서라고 적혀 있어요. 실제로 바뀌는 부분과 유지되는 계약이 무엇인지 보여 주고, 단순 함수 분리로 해결하지 않은 이유를 설명해 보세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '3 months')::date + INTERVAL '2 days'),
(900049, 900002, '00000000-0000-4000-8000-000000900010', 'API 설계', '운영 지표 대시보드에는 그래프를 추가한 사실보다 어떤 판단에 도움이 됐는지 적으면 좋겠어요. 오류율 상승을 발견하고 배포 변경과 연결해 원인을 좁힌 사례가 있다면 더 강한 내용이 돼요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '4 months')::date + INTERVAL '2 days'),
(900050, 900003, '00000000-0000-4000-8000-000000900015', '보안', '프로젝트 일정이 밀렸을 때 모든 기능을 끝내려 하기보다 핵심 흐름을 먼저 완성한 판단이 좋아요. 줄인 범위와 끝까지 유지한 사용자 경험을 구체적으로 써 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '4 months')::date + INTERVAL '2 days'),
(900051, 900004, '00000000-0000-4000-8000-000000900002', '회고', '이미지 최적화에서 용량 감소 외에 화질과 레이아웃 이동도 확인했나요? 화면 크기에 따라 다른 이미지를 제공한 기준과 실제 사용자 환경에서 확인한 내용을 넣어 보세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '4 months')::date + INTERVAL '2 days'),
(900052, 900005, '00000000-0000-4000-8000-000000900007', '포트폴리오', '오류를 잡은 뒤 기본값을 반환하는 코드가 있었는데, 실제 실패를 숨길 가능성이 있어요. 빈 결과와 조회 실패를 구분하도록 바꾼 이유를 설명하면 API 계약에 대한 이해가 드러나요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '5 months')::date + INTERVAL '2 days'),
(900053, 900006, '00000000-0000-4000-8000-000000900012', '캐시', '인턴 경험을 업무 목록으로만 정리하기보다 전달받은 문제와 본인이 제안한 해결책을 나눠 보세요. 작은 수정이어도 사용자의 반복 작업을 줄인 변화라면 충분히 소개할 만해요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '5 months')::date + INTERVAL '2 days'),
(900054, 900007, '00000000-0000-4000-8000-000000900017', '비동기 처리', '마지막 프로젝트는 결과보다 다음 단계가 길게 적혀 있어 완성한 범위가 흐려져요. 지금 동작하는 사용자 흐름, 확인한 한계, 앞으로 할 일을 구분하고 검증한 결과를 먼저 배치해 주세요.', false, NULL, (date_trunc('month', CURRENT_DATE) - INTERVAL '5 months')::date + INTERVAL '2 days')
